import httpx
from django.conf import settings
from rest_framework.exceptions import APIException


class ProductServiceError(APIException):
    status_code = 502
    default_detail = "سرویس محصولات در دسترس نیست."


class ProductClient:
    base_url = settings.PRODUCT_SERVICE_URL

    @classmethod
    def get_product(cls, product_id):
        try:
            response = httpx.get(
                f"{cls.base_url}/api/products/{product_id}/",
                timeout=5.0,
                headers={"X-Service-Token": settings.SERVICE_TOKEN},
            )
            response.raise_for_status()
            return response.json()
        except httpx.HTTPError as exc:
            raise ProductServiceError() from exc

    @classmethod
    def check_stock(cls, product_id, quantity):
        try:
            response = httpx.post(
                f"{cls.base_url}/api/products/{product_id}/check-stock/",
                json={"quantity": quantity},
                timeout=5.0,
            )
            response.raise_for_status()
            return response.json()["available"]
        except httpx.HTTPError:
            return False

