import time
import httpx
from django.conf import settings
from rest_framework.exceptions import APIException


class PaymentServiceError(APIException):
    status_code = 502
    default_detail = "سرویس پرداخت در دسترس نیست."


class CircuitBreaker:
    def __init__(self, threshold=5, timeout=60):
        self.failures = 0
        self.threshold = threshold
        self.timeout = timeout
        self.opened_at = None

    def is_open(self):
        return self.opened_at and time.time() - self.opened_at < self.timeout

    def record_success(self):
        self.failures = 0
        self.opened_at = None

    def record_failure(self):
        self.failures += 1
        if self.failures >= self.threshold:
            self.opened_at = time.time()


class PaymentClient:
    base_url = settings.PAYMENT_SERVICE_URL
    breaker = CircuitBreaker()

    @classmethod
    def charge(cls, amount, token, max_retries=3):
        if cls.breaker.is_open():
            raise PaymentServiceError("Circuit open")

        for attempt in range(max_retries):
            try:
                response = httpx.post(
                    f"{cls.base_url}/charge/",
                    json={"amount": str(amount), "token": token},
                    timeout=10.0,
                )
                response.raise_for_status()
                cls.breaker.record_success()
                return response.json()
            except httpx.HTTPError:
                if attempt == max_retries - 1:
                    cls.breaker.record_failure()
                    raise PaymentServiceError()
                time.sleep(2 ** attempt)
